pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract as owner
        vm.prank(address(this));
        c.initialize();

        // Set up a program operator (different from owner)
        address programOperator = address(0x123);
        vm.prank(address(this));
        c.programOperators(programOperator); // Not a setter, but we need to set programOperator
        // Actually, programOperators mapping must be set via a call; we simulate by directly using the owner to call update? No, we just set via vm.store? Not allowed.
        // Instead, we make the owner also a program operator to keep it simple.
        // Since owner is address(this), we can make address(this) a program operator.
        // But the test must use only external calls: so we call a function to set programOperators? There is none in the interface. So we must use vm.store to set the mapping? Not allowed.
        // Workaround: The owner is address(this) which is msg.sender in setUp. We can call create with encodedParameters and ownedBy as address(this).
        // First, we need roundImplementation and alloSettings set.
        // Deploy a dummy contract as roundImplementation
        address dummyRound = address(new RoundDummy());
        vm.prank(address(this));
        c.updateRoundImplementation(payable(dummyRound));

        // Set alloSettings to something non-zero
        vm.prank(address(this));
        c.updateAlloSettings(address(0x1));

        // Now we need address(this) to be a program operator. However, there is no public setter for programOperators. 
        // The only way is to directly use vm.store to set the mapping, but that's disallowed. 
        // Alternative: We can deploy a contract that acts as proxy? Not allowed.
        // Since the test cannot modify internal state via cheatcodes except vm.prank etc., we must accept that programOperators[msg.sender] is false by default.
        // Therefore, any call to create from anyone (including owner) will revert due to onlyProgramOperator modifier.
        // Hence the test must first ensure the caller is a program operator.
        // The only way to add a program operator is via an external function; there is none.
        // So the test is infeasible unless we use vm.store which is forbidden.
        // We'll skip this path and instead test the owner() difference directly without requiring create.
        // Simpler: After initialization, owner() should return address(this) in reference, address(0) in bug.
        // So we just call owner() and assert.
        // But the bug changes owner() to return address(0) unconditionally.
        address actualOwner = c.owner();
        assertTrue(actualOwner == address(this), "Owner mismatch");
    }
}

contract RoundDummy {
    function initialize(bytes calldata, address) external {}
}

